```

2. Create your NestJS model:

In your `models/index.ts` file, import the required schemas and create the model using Mongoose.

```typescript
import { Injectable } from '@nestjs/common';
import { Model } from 'mongoose';
import { UserSchema } from './schema/user.schema';
import { ProductSchema } from './schema/product.schema';

@Injectable()
export class AppModel {
  private readonly userModel: Model;
  private readonly productModel: Model;

  constructor() {
    this.userModel = UserSchema;
    this.productModel = ProductSchema;
  }

  async createUser(name: string, email: string) {
    return await this.userModel.create({ name, email });
  }

  async createProduct(title: string, description: string, price: number) {
    return await this.productModel.create({ title, description, price });
  }
}
```

