```php
<?php
/*
Plugin Name: Format WooCommerce Orders
Description: Formats WooCommerce orders to display order date, order ID, product name, quantity, price, and taxes in a specific format.
Version: 1.0
Author: Your Name
Author URI: https://yourwebsite.com
*/

function format_woocommerce_orders($orders) {
    $formatted_orders = array();

    foreach ($orders as $order) {
        $date = date('d/m/Y', strtotime($order->get_date_created()));
        $id = $order->get_order_number();
        $product_name = $order->get_product_name();
        $quantity = $order->get_quantity();
        $price = $order->get_total();
        $taxes = $order->get_total_tax();

        $formatted_orders[] = "$date,$id,$product_name,$quantity,$price,$taxes";
    }

    return implode("\n", $formatted_orders);
}

