```javascript
import { useState } from 'react';

function useTemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('C'); // Default unit is Celsius

  function handleUnitChange(event) {
    setUnit(event.target.value);
  }

  function handleTemperatureChange(event) {
    setTemperature(parseFloat(event.target.value));
  }

  function convertToFahrenheit() {
    return (temperature * 1.8) + 32;
  }

  function convertToCelsius() {
    return (temperature - 32) / 1.8;
  }

  return { temperature, unit, handleUnitChange, handleTemperatureChange, convertToFahrenheit, convertToCelsius };
}

export default useTemperatureConverter;
```

