```javascript
function organizeWordsByLength(words) {
  const wordLengths = {};

  for (const word of words) {
    const length = word.length;
    if (!wordLengths[length]) {
      wordLengths[length] = [];
    }
    wordLengths[length].push(word);
  }

  return Object.entries(wordLengths).map(([length, words]) => ({ word: words[0], length }));
}

