To convert the command-line arguments (argv) to a null-terminated C string, you can use the following C code:

```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    char *cstring = NULL;

    // Allocate memory for the C string
    cstring = malloc((argc + 1) * sizeof(char));
    if (cstring == NULL) {
        printf("Error: Could not allocate memory for the C string\n");
        return 1;
    }

    // Copy the command-line arguments to the C string
    for (int i = 0; i < argc; i++) {
        strcat(cstring, argv[i]);
        strcat(cstring, " ");
    }

    // Add a null terminator to the C string
    cstring[strlen(cstring)] = '\0';

    // Print the C string
    printf("C String: %s\n", cstring);

    // Free the memory allocated for the C string
    free(cstring);

    return 0;
}
```

This code will create a new C string that contains all the command-line arguments separated by spaces. The C string is allocated using `malloc()`, and the memory is freed using `free()` after the C string is printed.

