2. Create a JavaScript file (e.g., `prime_numbers.js`) with the following content:

```javascript
const primeNumbers = [3, 7, 13, 19];
const primeNumbersList = document.getElementById('primeNumbers');

function displayPrimeNumbers() {
    primeNumbersList.innerHTML = '';
    for (let i = 0; i < primeNumbers.length; i++) {
        const primeNumber = primeNumbers[i];
        const listItem = document.createElement('li');
        listItem.textContent = primeNumber;
        primeNumbersList.appendChild(listItem);
    }
}

function calculateProduct() {
    const product = primeNumbers.reduce((acc, curr) => acc * curr, 1);
    console.log(`The product of the prime numbers is ${product}.`);
}

displayPrimeNumbers();
calculateProduct();
```

Certainly! Here are four different methods to open and close the camera and microphone in JavaScript:

1. Using the `getUserMedia` API:

```javascript
async function openCamera() {
  const stream = await navigator.mediaDevices.getUserMedia({ video: true });
  return stream;
}

async function closeCamera(stream) {
  if (stream) {
    await stream.getTracks().forEach((track) => track.stop());
    await stream.release();
  }
}

async function openMicrophone() {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  return stream;
}

async function closeMicrophone(stream) {
  if (stream) {
    await stream.getTracks().forEach((track) => track.stop());
    await stream.release();
  }
}
```

2. Using the `MediaStreamTrack` API:

```javascript
function openCamera() {
  const videoTrack = new MediaStreamTrack();
  videoTrack.kind = 'video';
  videoTrack.label = 'Camera';

  const stream = new MediaStream([videoTrack]);
  return stream;
}

