Here's the `redis.js` file inside the `utils` folder:

```javascript
class RedisClient {
  constructor() {
    const { REDIS_CLIENT } = process.env;

    this.client = require('redis').createClient(REDIS_CLIENT);

    this.client.on('error', (err) => {
      console.error('Error with Redis Client:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (error) {
      console.error('Error checking Redis connection:', error);
      return false;
    }
  }

  async get(key) {
    try {
      const result = await this.client.get(key);
      return result;
    } catch (error) {
      console.error('Error getting from Redis:', error);
      throw error;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (error) {
      console.error('Error setting in Redis:', error);
      throw error;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (error) {
      console.error('Error deleting from Redis:', error);
      throw error;
    }
  }
}

const redisClient = new RedisClient();

module.exports = { redisClient };
```

Make sure to replace `REDIS_CLIENT` with your actual Redis connection string in the `constructor`.

